const MAP: Record<string, BlogArticle> = Object.fromEntries(
  BLOG_ARTICLES.map((a) => [a.slug, a]),
);

export function getBlogArticle(slug: string): BlogArticle | undefined {
  return MAP[slug];
}

export function getBlogArticleSlugs(): string[] {
  return BLOG_ARTICLES.map((a) => a.slug);
}
